import { defineCollection } from 'astro:content';
import { z } from 'astro/zod';
import { docsLoader } from '@astrojs/starlight/loaders';
import { docsSchema } from '@astrojs/starlight/schema';

// src/content/docs/ is generated by scripts/sync-docs.mjs; never edit it.
// `strapline`: a page's one-line strapline, shown directly beneath its title (PageTitle.astro), as on the four
// audience pages.
export const collections = {
	docs: defineCollection({
		loader: docsLoader(),
		schema: docsSchema({ extend: z.object({ strapline: z.string().optional() }) }),
	}),
};
